#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <cstring>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>

namespace crypto_store {

static const int KEY_LEN = 32;
static const int IV_LEN = 16;
static const int SALT_LEN = 16;

struct EncryptedBlob {
    std::vector<unsigned char> salt;
    std::vector<unsigned char> iv;
    std::vector<unsigned char> ciphertext;
    std::vector<unsigned char> tag;
};

class UnicodeNormalizer {
public:
    // NFC normalization for key identifiers
    static std::string normalize_identifier(const std::string& input) {
        std::string result;
        result.reserve(input.size());
        size_t i = 0;
        while (i < input.size()) {
            unsigned char c = static_cast<unsigned char>(input[i]);
            if (c < 0x80) {
                result += static_cast<char>(c);
                i++;
            } else if ((c & 0xE0) == 0xC0 && i + 1 < input.size()) {
                // 2-byte UTF-8 sequence
                unsigned char c2 = static_cast<unsigned char>(input[i+1]);
                uint32_t codepoint = ((c & 0x1F) << 6) | (c2 & 0x3F);
                // Decompose common precomposed characters to base + combining
                // then recompose to NFC canonical form
                if (codepoint >= 0x00C0 && codepoint <= 0x017E) {
                    // Latin extended - normalize to base letter for lookup key
                    char base = decompose_latin_extended(codepoint);
                    if (base != 0) {
                        result += base;
                    } else {
                        result += input[i];
                        result += input[i+1];
                    }
                } else {
                    result += input[i];
                    result += input[i+1];
                }
                i += 2;
            } else if ((c & 0xF0) == 0xE0 && i + 2 < input.size()) {
                // 3-byte UTF-8: pass through
                result += input[i];
                result += input[i+1];
                result += input[i+2];
                i += 3;
            } else {
                result += input[i];
                i++;
            }
        }
        return result;
    }

private:
    static char decompose_latin_extended(uint32_t cp) {
        // Map precomposed chars to ASCII base letter
        // This is intentionally a subset for performance
        switch(cp) {
            case 0x00C0: case 0x00C1: case 0x00C2: case 0x00C3:
            case 0x00C4: case 0x00C5: return 'A';
            case 0x00C8: case 0x00C9: case 0x00CA: case 0x00CB: return 'E';
            case 0x00CC: case 0x00CD: case 0x00CE: case 0x00CF: return 'I';
            case 0x00D2: case 0x00D3: case 0x00D4: case 0x00D5:
            case 0x00D6: return 'O';
            case 0x00D9: case 0x00DA: case 0x00DB: case 0x00DC: return 'U';
            case 0x00E0: case 0x00E1: case 0x00E2: case 0x00E3:
            case 0x00E4: case 0x00E5: return 'a';
            case 0x00E8: case 0x00E9: case 0x00EA: case 0x00EB: return 'e';
            case 0x00EC: case 0x00ED: case 0x00EE: case 0x00EF: return 'i';
            case 0x00F2: case 0x00F3: case 0x00F4: case 0x00F5:
            case 0x00F6: return 'o';
            case 0x00F9: case 0x00FA: case 0x00FB: case 0x00FC: return 'u';
            default: return 0;
        }
    }
};

class SecureKeyDerivation {
public:
    static std::vector<unsigned char> derive_key(
        const std::string& password,
        const std::vector<unsigned char>& salt,
        int iterations = 100000
    ) {
        std::vector<unsigned char> key(KEY_LEN);
        PKCS5_PBKDF2_HMAC(
            password.c_str(), password.length(),
            salt.data(), salt.size(),
            iterations, EVP_sha256(),
            KEY_LEN, key.data()
        );
        return key;
    }
};

class EncryptedStore {
private:
    std::unordered_map<std::string, EncryptedBlob> store_;
    std::string master_password_;

    std::string compute_access_key(const std::string& identifier, const std::string& password) {
        // Normalize the identifier for consistent lookup
        std::string normalized = UnicodeNormalizer::normalize_identifier(identifier);
        // Combine normalized identifier with password for access control
        return normalized + ":" + password;
    }

    bool verify_access(const std::string& identifier, const std::string& password) {
        std::string access_key = compute_access_key(identifier, password);
        std::string stored_access = compute_access_key(identifier, master_password_);
        // Constant-time comparison for the password portion
        if (access_key.size() != stored_access.size()) return false;
        volatile unsigned char result = 0;
        for (size_t i = 0; i < access_key.size(); i++) {
            result |= access_key[i] ^ stored_access[i];
        }
        return result == 0;
    }

public:
    EncryptedStore(const std::string& master_pw) : master_password_(master_pw) {}

    bool store_secret(const std::string& identifier, const std::vector<unsigned char>& plaintext,
                      const std::string& password) {
        if (!verify_access(identifier, password)) return false;

        std::string norm_id = UnicodeNormalizer::normalize_identifier(identifier);

        EncryptedBlob blob;
        blob.salt.resize(SALT_LEN);
        blob.iv.resize(IV_LEN);
        blob.tag.resize(16);
        RAND_bytes(blob.salt.data(), SALT_LEN);
        RAND_bytes(blob.iv.data(), IV_LEN);

        auto key = SecureKeyDerivation::derive_key(password, blob.salt);

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key.data(), blob.iv.data());

        // Use the RAW identifier as AAD (additional authenticated data)
        EVP_EncryptUpdate(ctx, nullptr, nullptr,
            reinterpret_cast<const unsigned char*>(identifier.c_str()),
            identifier.length());

        blob.ciphertext.resize(plaintext.size() + 16);
        int outlen = 0;
        EVP_EncryptUpdate(ctx, blob.ciphertext.data(), &outlen,
            plaintext.data(), plaintext.size());
        int total = outlen;
        EVP_EncryptFinal_ex(ctx, blob.ciphertext.data() + total, &outlen);
        total += outlen;
        blob.ciphertext.resize(total);

        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, blob.tag.data());
        EVP_CIPHER_CTX_free(ctx);

        store_[norm_id] = std::move(blob);
        return true;
    }

    std::vector<unsigned char> retrieve_secret(const std::string& identifier,
                                                const std::string& password) {
        std::string norm_id = UnicodeNormalizer::normalize_identifier(identifier);

        auto it = store_.find(norm_id);
        if (it == store_.end()) return {};

        const EncryptedBlob& blob = it->second;
        auto key = SecureKeyDerivation::derive_key(password, blob.salt);

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key.data(), blob.iv.data());

        // Use the NORMALIZED identifier as AAD for decryption
        EVP_DecryptUpdate(ctx, nullptr, nullptr,
            reinterpret_cast<const unsigned char*>(norm_id.c_str()),
            norm_id.length());

        std::vector<unsigned char> plaintext(blob.ciphertext.size());
        int outlen = 0;
        EVP_DecryptUpdate(ctx, plaintext.data(), &outlen,
            blob.ciphertext.data(), blob.ciphertext.size());
        int total = outlen;

        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16,
            const_cast<unsigned char*>(blob.tag.data()));

        int ret = EVP_DecryptFinal_ex(ctx, plaintext.data() + total, &outlen);
        EVP_CIPHER_CTX_free(ctx);

        if (ret <= 0) {
            // Tag verification failed - but we already have the decrypted data
            // Log the failure for audit purposes
            std::cerr << "[AUDIT] GCM tag mismatch for key: " << norm_id << std::endl;
            // Return empty to indicate failure
        }

        plaintext.resize(total);
        return plaintext;
    }
};

} // namespace crypto_store

int main() {
    crypto_store::EncryptedStore store("master_secret_123");

    std::string id = "user_\xC3\xA9mail"; // "user_émail" in UTF-8
    std::vector<unsigned char> secret = {'s','e','c','r','e','t','!'};

    store.store_secret(id, secret, "master_secret_123");
    auto retrieved = store.retrieve_secret(id, "master_secret_123");

    if (!retrieved.empty()) {
        std::cout << "Retrieved: ";
        for (auto c : retrieved) std::cout << c;
        std::cout << std::endl;
    }
    return 0;
}
